current.custom_css:
.m-menu .m-menu__item .m-menu__link--main {
  font-weight: 700;
}
body .m-promotion--header svg { height: auto;
max-width: unset;
 }
body .m-promotion--header .m-promotion__icon { margin-right: 20px; }
.m-custom-slideshow .m-slide__description p {
  font-weight: 700;
  font-size: 20px;
}
.m-custom-content-section .m-custom-image-card-1 .m-image-card__heading {
    font-size: 24px;
  line-height: 1.3;
  letter-spacing: 1px;
}
.m-custom-content-section .m-custom-image-card-1 .m-image-card__heading { 
  line-height: 1.167;
  letter-spacing: 3px;
}
[data-section-type="custom-content"]:last-child
  .sf__scrolling-text[data-style="text-outline"][data-outline-thickness="thin"]
  em {
  -webkit-text-stroke-width: 0.5px;
  -webkit-text-fill-color: rgba(0, 0, 0, 0);
  font-style: italic;
}
[data-section-type="custom-content"]:last-child
  .sf__scrolling-text[data-style="text-outline"]
  em {
  -webkit-text-stroke-color: #dfdfdf;
}
[data-section-type="custom-content"]:last-child
  .sf__scrolling-text
  .sf__scrolling-text-inner
  span.custom {
  padding: 0 25px;
}
[data-section-type="custom-content"]:last-child
  .sf__scrolling-text.font_size_11vh
  * {
  font-size: 110px;
  letter-spacing: 10px;
}
.m-custom-newsletters .m-newsletter-section__heading {
  line-height: 1.15;
  letter-spacing: 2px;
}
.m-footer .m-footer--block .m-footer--block-title {
  font-size: 14px;
  font-weight: 700;
}
.m-section__heading {
  letter-spacing: 2px;
}
.m-product-card__title a,
.m-collection-card__title a {
  font-weight: 700 !important;
  text-transform: uppercase;
}
.m-custom-newsletters .m-section-my {
  margin-top: -80px;
  position: relative;
}
@media (min-width: 1024px) {
  .m-footer--bottom-inner {
    border-top: 1px solid #d8d8d8;
  }
}
@media (min-width: 1280px) {
  .m-custom-newsletters .m-newsletter-section__heading {
    font-size: 40px;
  }
}
@media (min-width: 1536px) {
.m-custom-slideshow .m-slide__content .m-slide__title {
    font-size: 80px;
    margin-bottom: 18px;
  }

  .m-custom-newsletters .m-section-my {
    margin-top: -140px;
    position: relative;
  }
}
@media (max-width: 767px) {
  .m-custom-slideshow .m-slide__button .m-button--secondary {
    width: 100%;
  }
}
